name = #{name,jdbcType=VARCHAR}, category_id = #{categoryId,jdbcType=BIGINT}, price = #{price,jdbcType=DECIMAL}, image = #{image,jdbcType=VARCHAR}, description = #{description,jdbcType=VARCHAR}, status = #{status,jdbcType=INTEGER}, update_time = #{updateTime,jdbcType=TIMESTAMP}, update_user = #{updateUser,jdbcType=BIGINT},
where id = #{id,jdbcType=BIGINT}
